var prevAnimKeyIndex = Math.max(nearestAnimKey.index - (nearestAnimKey.time > time), 1);
var blink = Math.sin(Math.PI * (time - animProp.key(prevAnimKeyIndex).time) * blinkSpeed);

var txtProp	= text.sourceText;
var isTyping = (
	time > animProp.key(1).time &&
	txtProp.valueAtTime(time - thisComp.frameDuration * 5) !== txtProp.valueAtTime(time) &&
	time < animProp.key(animProp.numKeys).time
);

if(showCursor == 1){
	if (isTyping) {
		100;
	} else {
		(blink >= 0) * 100;
	}
}else{
	0;
}

