var p = [0,0,0];
var r = vRaw('Radius'); if (false && isOdd) r += off; var totalAng = vRaw('Gap X'); var ang = degreesToRadians((totalAng/total)*effIdx + vRaw('Start Angle')); var circ = [Math.cos(ang)*r, Math.sin(ang)*r, 0]; var steps = [effIdx*vRaw('Step X'), effIdx*vRaw('Step Y'), effIdx*vRaw('Step Z')]; p = circ + steps;

